-- CIPCodeLookup
-- Tenant-scoped representation of a Classification of Instructional Programs (CIP) code definition
-- for a specific NCES revision, including code, title, description, and source lineage. Separate
-- from institutional academic disciplines and from the association of a CIP classification to a
-- course, program, discipline, or credential.
CREATE TABLE academics.cip_code_lookup (
    tenant_identifier                                UUID NOT NULL,
    cip_code_identifier                              TEXT NOT NULL,
    cip_code                                         TEXT NOT NULL,
    cip_title                                        TEXT NOT NULL,
    cip_description                                  TEXT,
    cip_revision_year                                INTEGER NOT NULL,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_cip_code_lookup PRIMARY KEY (tenant_identifier, cip_code_identifier)
);
COMMENT ON TABLE academics.cip_code_lookup IS 'Tenant-scoped representation of a Classification of Instructional Programs (CIP) code definition for a specific NCES revision, including code, title, description, and source lineage. Separate from institutional academic disciplines and from the association of a CIP classification to a course, program, discipline, or credential.';
COMMENT ON COLUMN academics.cip_code_lookup.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.cip_code_lookup.cip_code_identifier IS 'Unique GUIDE-owned identifier for the CIP code definition.';
COMMENT ON COLUMN academics.cip_code_lookup.cip_code IS 'Classification of Instructional Programs code as published for the specified revision year.';
COMMENT ON COLUMN academics.cip_code_lookup.cip_title IS 'Official or source-supplied human-readable title of the CIP code.';
COMMENT ON COLUMN academics.cip_code_lookup.cip_description IS 'Official or source-supplied description of the CIP code.';
