-- ClassOrganizationUnitOwnership
-- A tenant-scoped association linking a stable class offering (SIS section) to one owning or
-- administering internal organization unit. Preserves source ownership percentage without
-- inferring a primary owner or requiring all percentages to total 100.
CREATE TABLE academics.class_organization_unit_ownership (
    tenant_identifier                                UUID NOT NULL,
    class_identifier                                 TEXT NOT NULL,
    organization_unit_identifier                     TEXT NOT NULL,
    ownership_percentage                             NUMERIC,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_class_organization_unit_ownership PRIMARY KEY (tenant_identifier, class_identifier, organization_unit_identifier)
);
COMMENT ON TABLE academics.class_organization_unit_ownership IS 'A tenant-scoped association linking a stable class offering (SIS section) to one owning or administering internal organization unit. Preserves source ownership percentage without inferring a primary owner or requiring all percentages to total 100.';
COMMENT ON COLUMN academics.class_organization_unit_ownership.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.class_organization_unit_ownership.class_identifier IS 'Class offering associated with the owning organization unit.';
COMMENT ON COLUMN academics.class_organization_unit_ownership.organization_unit_identifier IS 'Internal organization unit that owns or administers the class.';
COMMENT ON COLUMN academics.class_organization_unit_ownership.ownership_percentage IS 'Source-reported percentage associated with the organization-unit ownership relationship.';
