COMMENT ON COLUMN academics.competency.competency_context IS 'Indicates context in which comptetency hierarchy applies (unspecified, account, course, college, department)';
COMMENT ON COLUMN academics.competency.status IS 'Status of the competency (active, inactive)';
COMMENT ON COLUMN academics.competency.source_system_key_value IS 'Unique identifier of this record in the source system';
