-- CourseLookup
-- A lookup table containing a list of courses that may be offered by a school or institution. The
-- details include title, description, units, and other descriptive information.
CREATE TABLE academics.course_lookup (
    tenant_identifier                                UUID NOT NULL,
    course_identifier                                TEXT NOT NULL,
    course_recognized_organization_identifier        TEXT,
    course_regulated_by_organization_identifier      TEXT,
    information_source_organization_identifier       TEXT,
    course_offered_by_organization_identifier        TEXT,
    score_scale_identifier                           TEXT,
    source_system_identifier                         TEXT,
    academic_subject_identifier                      TEXT,
    cip_code_identifier                              TEXT,
    display_identifier                               TEXT,
    course_status_identifier                         TEXT,
    original_course_code                             TEXT,
    offering_start_date                              DATE,
    offering_end_date                                DATE,
    subject_abbreviation                             TEXT,
    number                                           TEXT NOT NULL,
    title                                            TEXT NOT NULL,
    description                                      TEXT,
    repeatability_indicator                          BOOLEAN NOT NULL DEFAULT FALSE,
    repeatability_maximum_credit                     NUMERIC,
    repeatability_maximum_number                     INTEGER,
    syllabus_url                                     TEXT,
    learning_outcomes                                TEXT,
    resources                                        TEXT,
    credit_unit_type                                 TEXT,
    credit_value                                     NUMERIC,
    instruction_site_name                            TEXT,
    instruction_site_type                            TEXT,
    level_type                                       TEXT,
    honors_type                                      TEXT,
    credit_basis_type                                TEXT,
    credit_level_type                                TEXT,
    instruction_method                               TEXT,
    narrative_explanation_grade                      TEXT,
    repeat_code                                      TEXT,
    academic_grade_scale_code                        TEXT,
    certification_name_association                   TEXT,
    code_system                                      TEXT,
    contact_minutes                                  NUMERIC,
    duration                                         TEXT,
    estimated_cost                                   TEXT,
    language_of_instruction                          TEXT,
    learning_standard                                TEXT,
    online_availability                              TEXT,
    standard_association_indicator                   BOOLEAN,
    subject_url                                      TEXT,
    instructional_delivery_mode                      TEXT,
    level_characteristic                             TEXT,
    applicable_education_level                       TEXT,
    interaction_mode                                 TEXT,
    nces_college_course_map_code                     TEXT,
    corequisite_site_restriction_indicator           BOOLEAN,
    allow_multiple_section_waitlist_indicator        BOOLEAN,
    advanced_placement_course_code                   TEXT,
    developmental_education_type                     TEXT,
    work_based_learning_type                         TEXT,
    status                                           TEXT NOT NULL,
    syllabus_body                                    TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_course_lookup PRIMARY KEY (tenant_identifier, course_identifier)
);
COMMENT ON TABLE academics.course_lookup IS 'A lookup table containing a list of courses that may be offered by a school or institution. The details include title, description, units, and other descriptive information.';
COMMENT ON COLUMN academics.course_lookup.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.course_lookup.course_identifier IS 'The actual code that identifies the organization of subject matter and related learning experiences provided for the instruction of students';
COMMENT ON COLUMN academics.course_lookup.course_recognized_organization_identifier IS 'Agent that acknowledges the validity of the course';
COMMENT ON COLUMN academics.course_lookup.course_regulated_by_organization_identifier IS 'Quality assurance organization that enforces the legal requirements of the course';
COMMENT ON COLUMN academics.course_lookup.information_source_organization_identifier IS 'Organization identifier for the source of the information provided';
COMMENT ON COLUMN academics.course_lookup.course_offered_by_organization_identifier IS 'A unique number or alphanumeric code assigned to a school, school system, a state, business, or other agency or entity';
COMMENT ON COLUMN academics.course_lookup.score_scale_identifier IS 'Unique identifier for the score scale';
COMMENT ON COLUMN academics.course_lookup.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN academics.course_lookup.academic_subject_identifier IS 'Identifier for the canonical academic subject assigned to the course.';
COMMENT ON COLUMN academics.course_lookup.cip_code_identifier IS 'Identifier of the canonical Classification of Instructional Programs (CIP) code associated with this record.';
COMMENT ON COLUMN academics.course_lookup.display_identifier IS 'System-managed course identifier selected for display, independent of canonical identity and alternate identifiers.';
COMMENT ON COLUMN academics.course_lookup.course_status_identifier IS 'Governed lifecycle status of the course definition.';
COMMENT ON COLUMN academics.course_lookup.original_course_code IS 'Legacy or historical course code under which the course was previously listed, such as before a catalog renumbering or system conversion. This is a source-facing code, not a foreign key to another GUIDE course row.';
COMMENT ON COLUMN academics.course_lookup.offering_start_date IS 'The date on which the course first becomes available for institutional offering or catalog use. This is a course lifecycle attribute, not a revision identifier.';
COMMENT ON COLUMN academics.course_lookup.offering_end_date IS 'The date after which the course is no longer available for institutional offering or catalog use. This is a course lifecycle attribute, not a revision identifier.';
COMMENT ON COLUMN academics.course_lookup.subject_abbreviation IS 'The alphabetic abbreviation of the academic department or discipline offering the course.';
COMMENT ON COLUMN academics.course_lookup.number IS 'The official reference number portion of a course identifier. This number normally designates the level of the course as well as the level of the individual expected to enroll in the course.';
COMMENT ON COLUMN academics.course_lookup.title IS 'The descriptive name given to a course of study offered in a school or other institution or organization. In departmentalized classes at the elementary, secondary, and postsecondary levels (and for staff development activities), this refers to the name by which a course is identified (e.g., American History, English III). For elementary and other non-departmentalized classes, it refers to any portion of the instruction for which a grade or report is assigned (e.g. reading, composition, spelling, and language arts).';
COMMENT ON COLUMN academics.course_lookup.description IS 'Catalog description of the course''s subject matter, scope, and instructional content.';
COMMENT ON COLUMN academics.course_lookup.repeatability_indicator IS 'Indicates whether or not the course can be repeated for credit';
COMMENT ON COLUMN academics.course_lookup.repeatability_maximum_credit IS 'The maximum hours for which the course may be taken for credit';
