-- CredentialLookup
-- A lookup table that contains all existing approved and proposed credentials for issuance to
-- learners.
CREATE TABLE academics.credential_lookup (
    tenant_identifier                                UUID NOT NULL,
    credential_identifier                            TEXT NOT NULL,
    program_of_study_identifier                      TEXT,
    credential_type_identifier                       TEXT,
    information_source_organization_identifier       TEXT,
    source_system_identifier                         TEXT,
    endorsed_by_organization_identifier              TEXT,
    name                                             TEXT NOT NULL,
    abbreviation                                     TEXT,
    description                                      TEXT,
    narrative                                        TEXT,
    field_of_study                                   TEXT,
    uri                                              TEXT,
    credits_available                                NUMERIC,
    image_url                                        TEXT,
    image_caption                                    TEXT,
    approval_status                                  TEXT NOT NULL,
    status                                           TEXT NOT NULL,
    endorsed_indicator                               BOOLEAN,
    credential_engine_id                             TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_credential_lookup PRIMARY KEY (tenant_identifier, credential_identifier)
);
COMMENT ON TABLE academics.credential_lookup IS 'A lookup table that contains all existing approved and proposed credentials for issuance to learners.';
COMMENT ON COLUMN academics.credential_lookup.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.credential_lookup.credential_identifier IS 'Unique identifier for the credential or achievement';
COMMENT ON COLUMN academics.credential_lookup.program_of_study_identifier IS 'Unique identifier for a program of study offering';
COMMENT ON COLUMN academics.credential_lookup.credential_type_identifier IS 'Reference-code value identifying the type of academic credential, such as degree, certificate, diploma, or microcredential.';
COMMENT ON COLUMN academics.credential_lookup.information_source_organization_identifier IS 'Organization identifier for the source of the information provided';
COMMENT ON COLUMN academics.credential_lookup.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN academics.credential_lookup.endorsed_by_organization_identifier IS 'A unique number or alphanumeric code assigned to a school, school system, a state, business, or other agency or entity';
COMMENT ON COLUMN academics.credential_lookup.name IS 'Official name of the academic credential, degree, certificate, or other recognized achievement.';
COMMENT ON COLUMN academics.credential_lookup.abbreviation IS 'The abbreviation or short name used to identify the credential or academic award';
COMMENT ON COLUMN academics.credential_lookup.description IS 'Detailed description of the academic credential, degree, certificate, or other recognized achievement.';
COMMENT ON COLUMN academics.credential_lookup.narrative IS 'A narrative of what is needed to earn the achievement';
COMMENT ON COLUMN academics.credential_lookup.field_of_study IS 'Category, subject, area of study, discipline, or general branch of knowledge';
COMMENT ON COLUMN academics.credential_lookup.uri IS 'A Uniform Resource Identifier for the credential';
COMMENT ON COLUMN academics.credential_lookup.credits_available IS 'Credit hours associated with this entity, or credit hours possible';
COMMENT ON COLUMN academics.credential_lookup.image_url IS 'A URL to the image representing the credential';
COMMENT ON COLUMN academics.credential_lookup.image_caption IS 'The caption for the image representing the credential';
COMMENT ON COLUMN academics.credential_lookup.approval_status IS 'Indicates the status of the credential between initial proposal and final approval for issuance';
COMMENT ON COLUMN academics.credential_lookup.status IS 'Status of the lookup item (active, inactive)';
COMMENT ON COLUMN academics.credential_lookup.endorsed_indicator IS 'Indicates whether the curruclum for this credential''s program has been provided by or endorsed by an industry-recognized credentialing body';
COMMENT ON COLUMN academics.credential_lookup.credential_engine_id IS 'Credential registry number or CTID serving as the primary unique identifier in the Credential Engine Credential Registry.';
COMMENT ON COLUMN academics.credential_lookup.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN academics.credential_lookup.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN academics.credential_lookup.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN academics.credential_lookup.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN academics.credential_lookup.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.credential_lookup.created_date IS 'Date record was created';
COMMENT ON COLUMN academics.credential_lookup.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.credential_lookup.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.credential_lookup.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.credential_lookup.deleted_date IS 'Date and time record was deleted';

