-- Enrollment
-- A tenant-scoped person-to-learning-offering enrollment record. For section registrations it
-- preserves registration status, credit, grading choices, involvement dates, overrides, and
-- waitlist position.
CREATE TABLE academics.enrollment (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    enrollment_identifier                            TEXT NOT NULL,
    role_identifier                                  TEXT NOT NULL,
    program_of_study_identifier                      TEXT,
    course_identifier                                TEXT,
    class_identifier                                 TEXT,
    source_system_identifier                         TEXT,
    academic_level_identifier                        TEXT,
    section_registration_status_identifier           TEXT NOT NULL,
    grade_scheme_identifier                          TEXT,
    grade_mode_identifier                            TEXT,
    override_term_identifier                         TEXT,
    override_site_identifier                         TEXT,
    active_indicator                                 BOOLEAN NOT NULL DEFAULT FALSE,
    status                                           TEXT NOT NULL,
    exit_reason                                      TEXT,
    start_date                                       TIMESTAMP WITH TIME ZONE,
    end_date                                         TIMESTAMP WITH TIME ZONE,
    offering_type                                    TEXT,
    last_active_online_date                          DATE,
    total_active_online_time                         INTEGER,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    registration_status_date                         DATE,
    registration_credit_measure                      TEXT,
    registration_credit_value                        NUMERIC,
    originally_registered_date                       DATE,
    involvement_start_date                           DATE,
    involvement_end_date                             DATE,
    waitlist_priority_number                         INTEGER,
    CONSTRAINT pk_enrollment PRIMARY KEY (tenant_identifier, enrollment_identifier)
);
COMMENT ON TABLE academics.enrollment IS 'A tenant-scoped person-to-learning-offering enrollment record. For section registrations it preserves registration status, credit, grading choices, involvement dates, overrides, and waitlist position.';
COMMENT ON COLUMN academics.enrollment.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.enrollment.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN academics.enrollment.enrollment_identifier IS 'Unique identifier for the enrollment';
COMMENT ON COLUMN academics.enrollment.role_identifier IS 'Unique identifier for the role';
COMMENT ON COLUMN academics.enrollment.program_of_study_identifier IS 'Unique identifier for a program of study offering';
COMMENT ON COLUMN academics.enrollment.course_identifier IS 'The actual code that identifies the organization of subject matter and related learning experiences provided for the instruction of students';
COMMENT ON COLUMN academics.enrollment.class_identifier IS 'Unique identifier for the class';
COMMENT ON COLUMN academics.enrollment.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN academics.enrollment.academic_level_identifier IS 'Academic level at which the learner registered for the section.';
COMMENT ON COLUMN academics.enrollment.section_registration_status_identifier IS 'Governed current status of the person-section registration.';
COMMENT ON COLUMN academics.enrollment.grade_scheme_identifier IS 'Governed grade scheme elected or assigned for the registration.';
COMMENT ON COLUMN academics.enrollment.grade_mode_identifier IS 'Governed grade-reporting mode elected or assigned for the registration.';
COMMENT ON COLUMN academics.enrollment.override_term_identifier IS 'Academic period applied as a registration-specific override.';
COMMENT ON COLUMN academics.enrollment.override_site_identifier IS 'Institutional site applied as a registration-specific override.';
COMMENT ON COLUMN academics.enrollment.active_indicator IS 'Used to identify if the enrollment described in this entity is currently active or inactive';
COMMENT ON COLUMN academics.enrollment.status IS 'The status of this enrollment (e.g. Pre-registered, Pending, Registered, Enrolled, Withdrawn, OnHold, WaitListed, etc.)';
COMMENT ON COLUMN academics.enrollment.exit_reason IS 'The circumstances under which the person exited from membership in the learning experience';
COMMENT ON COLUMN academics.enrollment.start_date IS 'The start date of the associated event';
COMMENT ON COLUMN academics.enrollment.end_date IS 'The end date of the associated event';
COMMENT ON COLUMN academics.enrollment.offering_type IS 'The type of education being offered (e.g. Collection, Course, Component)';
