-- EnrollmentAcademicOutcome
-- Current transcriptable academic outcome for a person and course/enrollment, including awarded
-- grade, credits, quality points, repeat treatment, and incomplete-lapse facts.
CREATE TABLE academics.enrollment_academic_outcome (
    tenant_identifier                                UUID NOT NULL,
    enrollment_academic_outcome_identifier           TEXT NOT NULL,
    person_identifier                                TEXT NOT NULL,
    enrollment_identifier                            TEXT,
    term_identifier                                  TEXT,
    course_identifier                                TEXT,
    grade_scheme_identifier                          TEXT,
    grade_definition_identifier                      TEXT,
    credit_category_identifier                       TEXT,
    current_grade_change_reason_identifier           TEXT,
    recorded_date                                    DATE,
    attempted_credit                                 NUMERIC,
    earned_credit                                    NUMERIC,
    gpa_quality_points                               NUMERIC,
    base_quality_points                              NUMERIC,
    repeat_grade_treatment_identifier                TEXT,
    incomplete_extension_date                        DATE,
    incomplete_default_grade_value                   TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_enrollment_academic_outcome PRIMARY KEY (tenant_identifier, enrollment_academic_outcome_identifier)
);
COMMENT ON TABLE academics.enrollment_academic_outcome IS 'Current transcriptable academic outcome for a person and course/enrollment, including awarded grade, credits, quality points, repeat treatment, and incomplete-lapse facts.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.enrollment_academic_outcome_identifier IS 'GUIDE-owned tenant-scoped identifier for the academic outcome.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.person_identifier IS 'Person to whom the academic outcome belongs.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.enrollment_identifier IS 'Person-to-offering enrollment that produced the outcome when directly resolvable.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.term_identifier IS 'Academic period in which the outcome was recorded.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.course_identifier IS 'Course associated with the transcriptable outcome when supplied independently of an enrollment identifier.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.grade_scheme_identifier IS 'Grade scheme governing the awarded grade.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.grade_definition_identifier IS 'Governed grade definition currently awarded for the outcome.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.credit_category_identifier IS 'Governed credit category associated with the outcome.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.current_grade_change_reason_identifier IS 'Reason associated with the most recently applied grade change when supplied by the source.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.recorded_date IS 'Date the current transcript grade/outcome was recorded.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.attempted_credit IS 'Credit attempted for the course or enrollment represented by this outcome.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.earned_credit IS 'Credit earned from the course or enrollment represented by this outcome.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.gpa_quality_points IS 'Weighted quality points used in grade-point-average calculation.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.base_quality_points IS 'Non-weighted or base quality points associated with the outcome.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.repeat_grade_treatment_identifier IS 'Governed treatment specifying how this repeated-course outcome participates in GPA calculation.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.incomplete_extension_date IS 'Date after which an incomplete grade may lapse or a default final grade may be applied.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.incomplete_default_grade_value IS 'Default final grade value to apply if incomplete work is not resolved by the applicable deadline.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.source_system_identifier IS 'Source system supplying the academic outcome.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.source_system_key_value IS 'Source-system identifier for the transcript-grade/outcome record.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.created_date IS 'Date and time the canonical row was created.';
COMMENT ON COLUMN academics.enrollment_academic_outcome.updated_date IS 'Date and time the canonical row was last updated.';

