    advanced_placement_credits_awarded               NUMERIC,
    course_total                                     INTEGER,
    credits_attempted_cumulative                     NUMERIC,
    credits_earned_cumulative                        NUMERIC,
    number_of_credits_attempted                      NUMERIC,
    number_of_credits_earned                         NUMERIC,
    doctoral_exams_required_type                     TEXT,
    doctoral_exam_taken_date                         DATE,
    graduate_or_doctoral_exam_results_status         TEXT,
    doctoral_candidacy_admit_indicator               TEXT,
    doctoral_candidacy_date                          DATE,
    thesis_or_dissertation_title                     TEXT,
    oral_defense_date                                DATE,
    oral_defense_completed_indicator                 BOOLEAN NOT NULL DEFAULT FALSE,
    receiving_location_of_instruction                TEXT,
    naics_code                                       TEXT,
    format                                           TEXT,
    credential_first_issued_date                     DATE,
    credential_issuance_date                         TIMESTAMP WITH TIME ZONE,
    credential_expiration_date                       DATE,
