COMMENT ON TABLE academics.learner_credential IS 'A table containing a history of certifications, credentials, badges, or programs of study for which a learner has pursued regardless of the outcome of completion.';
COMMENT ON COLUMN academics.learner_credential.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.learner_credential.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN academics.learner_credential.learner_credential_identifier IS 'Unique identifier for the learner''s credential history, either in-progress or completed credentials, covering certificates, diplomas, degrees, academic records, etc.';
COMMENT ON COLUMN academics.learner_credential.credential_identifier IS 'Unique identifier for the credential';
COMMENT ON COLUMN academics.learner_credential.program_of_study_identifier IS 'Unique identifier for a program of study offering';
COMMENT ON COLUMN academics.learner_credential.person_program_identifier IS 'Unique identifier for the person-program relationship associated with the awarded credential';
COMMENT ON COLUMN academics.learner_credential.term_identifier IS 'Unique identifier for a term';
COMMENT ON COLUMN academics.learner_credential.person_document_identifier IS 'Unique identifier for a person''s document';
COMMENT ON COLUMN academics.learner_credential.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN academics.learner_credential.name IS 'The name of the credential or academic award';
COMMENT ON COLUMN academics.learner_credential.uri IS 'Uniform resource identifier for the learner credential';
COMMENT ON COLUMN academics.learner_credential.program_of_study_name IS 'Name of the program of study offering';
COMMENT ON COLUMN academics.learner_credential.cip_code_identifier IS 'Identifier of the canonical Classification of Instructional Programs (CIP) code associated with this record.';
COMMENT ON COLUMN academics.learner_credential.date IS 'The year, month and day or year and month on which the credential or academic award was conferred';
COMMENT ON COLUMN academics.learner_credential.grade_point_average_cumulative IS 'Cumulative grade point average';
COMMENT ON COLUMN academics.learner_credential.grade_point_average_weighted_indicator IS 'Indicator that a grade point average was calculated with weighted factors';
COMMENT ON COLUMN academics.learner_credential.grade_point_average_official_indicator IS 'Indicator that the GradePointAverage was from an official source';
COMMENT ON COLUMN academics.learner_credential.high_school_diploma_type IS 'The type of diploma/credential that is awarded to a person in recognition of his/her completion of the curricular requirements';
COMMENT ON COLUMN academics.learner_credential.cohort_year IS 'The school year in which the student entered the baseline group used for computing completion rates (e.g. high school, program)';
COMMENT ON COLUMN academics.learner_credential.pesc_award_level_type IS 'The category of award conferred by a college, university, or other postsecondary education institution as official recognition for the successful completion of a program of study';
COMMENT ON COLUMN academics.learner_credential.ob_achievement_type IS 'The type of achievement';
COMMENT ON COLUMN academics.learner_credential.postsecondary_program_level IS 'Level of the degree program';
COMMENT ON COLUMN academics.learner_credential.level_conferred IS 'The category of award conferred by a college, university, or other postsecondary education institution as official recognition for the successful completion of a program of study';
COMMENT ON COLUMN academics.learner_credential.prerequisite_type IS 'Prerequisite conditions for earning an credential or academic award';
COMMENT ON COLUMN academics.learner_credential.requirements_url IS 'A URL to a page that describes the requirements for the credential';
COMMENT ON COLUMN academics.learner_credential.credit_hours_applied_other_program IS 'Codes identifying the set of credit hours taken in other programs or degrees that were applied to the individual''s degree';
COMMENT ON COLUMN academics.learner_credential.dqp_categories_of_learning IS 'The Lumina Foundation''s Degree Qualifications Profile offers reference points for what students should know and be able to do upon completion of associate, bachelor''s and master''s degrees – in any field of study. The DQP Categories of Learning provide a profile of what degrees mean within which specific proficiencies may be defined';
COMMENT ON COLUMN academics.learner_credential.professional_or_technical_academic_credential_conferred IS 'The category of credential conferred by a state occupational licensing entity or industry organization for competency in a specific area measured by a set of pre-established standards';
COMMENT ON COLUMN academics.learner_credential.high_school_student_class_rank IS 'The academic rank of a student in relation to his or her high school graduating class (e.g. 1, 2, 3) based on high school GPA';
COMMENT ON COLUMN academics.learner_credential.size_of_high_school_graduating_class IS 'Size of the learner''s high school graduation class';
COMMENT ON COLUMN academics.learner_credential.grade_point_average IS 'The value of the total quality points divided by the Credit Hours for Grade Point Average';
COMMENT ON COLUMN academics.learner_credential.dual_credit_dual_enrollment_credits_awarded IS 'The number of credits awarded a student by the postsecondary institution based on successful completion of dual credit/dual enrollment courses';
COMMENT ON COLUMN academics.learner_credential.advanced_placement_credits_awarded IS 'The number of credits awarded for an advanced placement exam';
COMMENT ON COLUMN academics.learner_credential.course_total IS 'The total number of courses listed on a transcript. Used as a check digit for integrity purposes.';
COMMENT ON COLUMN academics.learner_credential.credits_attempted_cumulative IS 'The cumulative number of credits a person attempts to earn by taking courses during their enrollment in their current education institution as well as those credits transferred from an education institution in which the person had been previously enrolled';
COMMENT ON COLUMN academics.learner_credential.credits_earned_cumulative IS 'The cumulative number of credits a person earns by completing courses or examinations during their enrollment in the current education institution as well as those credits transferred from an education institution in which the person had been previously enrolled';
COMMENT ON COLUMN academics.learner_credential.number_of_credits_attempted IS 'The number of credits that a student can earn for enrolling in and completing a given course';
COMMENT ON COLUMN academics.learner_credential.number_of_credits_earned IS 'The number of credits an individual earns by the successful completion of a course';
COMMENT ON COLUMN academics.learner_credential.doctoral_exams_required_type IS 'A qualifier identifying the types of exams required of doctoral level individuals';
COMMENT ON COLUMN academics.learner_credential.doctoral_exam_taken_date IS 'The date on which the individual took an exam for advancement in, continuation or completion of a doctoral program';
COMMENT ON COLUMN academics.learner_credential.graduate_or_doctoral_exam_results_status IS 'The individual''s status in completing exams required for graduate or doctoral degree programs';
COMMENT ON COLUMN academics.learner_credential.doctoral_candidacy_admit_indicator IS 'The individual''s status in being admitted as a doctoral candidate';
COMMENT ON COLUMN academics.learner_credential.doctoral_candidacy_date IS 'The date on which the individual was admitted to doctoral candidate status';
COMMENT ON COLUMN academics.learner_credential.thesis_or_dissertation_title IS 'The title of the thesis or dissertation';
COMMENT ON COLUMN academics.learner_credential.oral_defense_date IS 'The date on which the individual gave an oral defense';
COMMENT ON COLUMN academics.learner_credential.oral_defense_completed_indicator IS 'An indication of the individual''s completion of an oral defense. The requirement to conduct an oral defense by doctoral individuals may vary across institutions, programs, or fields of study.';
COMMENT ON COLUMN academics.learner_credential.receiving_location_of_instruction IS 'The type of location at which instruction or service takes place';
COMMENT ON COLUMN academics.learner_credential.naics_code IS 'ONET/OEWS: North American Industry Classification System (NAICS) code for the given industry';
COMMENT ON COLUMN academics.learner_credential.format IS 'The format in which the academic award or credential exists (e.g. OpenBadges 2.0)';
COMMENT ON COLUMN academics.learner_credential.credential_first_issued_date IS 'Date of the first time the learner was issued this credential';
COMMENT ON COLUMN academics.learner_credential.credential_issuance_date IS 'Timestamp of when the credential becomes valid';
COMMENT ON COLUMN academics.learner_credential.credential_expiration_date IS 'The year, month and day on which an active credential held by a person will expire';
COMMENT ON COLUMN academics.learner_credential.credential_description IS 'The description of the academic award or credential';
COMMENT ON COLUMN academics.learner_credential.credential_award_evidence_url IS 'A URL to a page that describes the evidence that the learner met the criteria for attainment of the credential award';
COMMENT ON COLUMN academics.learner_credential.credential_revoked_indicator IS 'Indicates whether the credential has been revoked by the credential provider';
COMMENT ON COLUMN academics.learner_credential.credential_revoked_reason IS 'Published reason for revocation of a credential award';
COMMENT ON COLUMN academics.learner_credential.self_asserted_indicator IS 'Indicates whether the credential is self asserted or not';
COMMENT ON COLUMN academics.learner_credential.status IS 'Indicates the status of the credential or academic award in the process between the learner selecting to achieve it and the achievement being issued, rejected, or revoked';
COMMENT ON COLUMN academics.learner_credential.narrative IS 'A narrative that connects multiple pieces of evidence';
COMMENT ON COLUMN academics.learner_credential.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN academics.learner_credential.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN academics.learner_credential.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN academics.learner_credential.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN academics.learner_credential.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.learner_credential.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.learner_credential.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.learner_credential.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.learner_credential.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.learner_credential.deleted_date IS 'Date and time record was deleted';

