    source_system_updated_date                       TIMESTAMP WITH TIME ZONE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_learner_credential_discipline PRIMARY KEY (tenant_identifier, learner_credential_discipline_identifier)
);
COMMENT ON TABLE academics.learner_credential_discipline IS 'Tenant-scoped association between a learner credential and one or more academic disciplines or fields of study represented by canonical AcademicDiscipline records.';
COMMENT ON COLUMN academics.learner_credential_discipline.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.learner_credential_discipline.learner_credential_discipline_identifier IS 'Unique tenant-scoped identifier for a learner-credential-to-academic-discipline relationship';
COMMENT ON COLUMN academics.learner_credential_discipline.learner_credential_identifier IS 'Learner credential to which the academic discipline applies';
COMMENT ON COLUMN academics.learner_credential_discipline.academic_discipline_identifier IS 'Canonical academic discipline or field of study associated with the learner credential';
COMMENT ON COLUMN academics.learner_credential_discipline.source_system_identifier IS 'Identifier of the source system that supplied the relationship';
COMMENT ON COLUMN academics.learner_credential_discipline.source_system_key_value IS 'Source-system identifier for the learner-credential discipline relationship when independently supplied or deterministically generated';
COMMENT ON COLUMN academics.learner_credential_discipline.source_system_created_date IS 'Date and time the source relationship was created';
COMMENT ON COLUMN academics.learner_credential_discipline.source_system_updated_date IS 'Date and time the source relationship was last modified';
COMMENT ON COLUMN academics.learner_credential_discipline.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.learner_credential_discipline.created_date IS 'Date record was created';
COMMENT ON COLUMN academics.learner_credential_discipline.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.learner_credential_discipline.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.learner_credential_discipline.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.learner_credential_discipline.deleted_date IS 'Date and time record was deleted';

