COMMENT ON TABLE academics.person_program IS 'Tenant-scoped relationship between a person and an academic program across recruitment, application, matriculation, and outcome stages, including the governing academic catalog and exact program curriculum when known.';
COMMENT ON COLUMN academics.person_program.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.person_program.person_program_identifier IS 'Unique tenant-scoped identifier for a person-program relationship';
COMMENT ON COLUMN academics.person_program.person_identifier IS 'Person associated with the academic program';
COMMENT ON COLUMN academics.person_program.program_of_study_identifier IS 'Academic program associated with the person';
COMMENT ON COLUMN academics.person_program.program_objective_identifier IS 'Governed classification of the lifecycle objective of the person-program relationship';
COMMENT ON COLUMN academics.person_program.program_status_identifier IS 'Governed current status of the person-program relationship';
COMMENT ON COLUMN academics.person_program.program_enrollment_status_identifier IS 'Institution-defined detailed status of the person-program enrollment';
COMMENT ON COLUMN academics.person_program.admission_category_identifier IS 'Governed admission or entry category associated with the person-program relationship, such as first-time, transfer, or returning.';
COMMENT ON COLUMN academics.person_program.program_start_date IS 'Actual or institutionally recognized beginning date of the person-program relationship';
COMMENT ON COLUMN academics.person_program.program_end_date IS 'Actual or institutionally recognized ending date of the person-program relationship';
COMMENT ON COLUMN academics.person_program.reporting_start_date IS 'Alternate effective start date used for reporting';
COMMENT ON COLUMN academics.person_program.reporting_end_date IS 'Alternate effective end date used for reporting';
COMMENT ON COLUMN academics.person_program.expected_graduation_date IS 'Expected calendar date of completion of the academic program';
COMMENT ON COLUMN academics.person_program.starting_term_identifier IS 'Academic period associated with the beginning of the person-program relationship';
COMMENT ON COLUMN academics.person_program.expected_graduation_term_identifier IS 'Academic period in which program completion is expected';
COMMENT ON COLUMN academics.person_program.primary_program_indicator IS 'Indicates whether this is the person''s designated primary academic program relationship';
COMMENT ON COLUMN academics.person_program.academic_level_identifier IS 'Current or source-designated academic level associated with the person-program relationship';
COMMENT ON COLUMN academics.person_program.site_identifier IS 'Institutional site or campus associated with the person-program relationship';
COMMENT ON COLUMN academics.person_program.academic_catalog_identifier IS 'Academic catalog edition governing or associated with the person-program relationship.';
COMMENT ON COLUMN academics.person_program.program_curriculum_identifier IS 'Exact program curriculum against which this person-program relationship is governed or evaluated.';
COMMENT ON COLUMN academics.person_program.source_system_identifier IS 'Identifier of the source system that supplied the record';
COMMENT ON COLUMN academics.person_program.source_system_key_value IS 'Source-system identifier for the person-program relationship';
COMMENT ON COLUMN academics.person_program.source_system_created_date IS 'Date and time the source record was created';
COMMENT ON COLUMN academics.person_program.source_system_updated_date IS 'Date and time the source record was last modified';
COMMENT ON COLUMN academics.person_program.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.person_program.created_date IS 'Date record was created';
COMMENT ON COLUMN academics.person_program.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.person_program.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.person_program.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.person_program.deleted_date IS 'Date and time record was deleted';
COMMENT ON COLUMN academics.person_program.program_owner_organization_unit_identifier IS 'Organizational unit administratively responsible for the person-program relationship';

