-- PersonProgramProgressEvaluation
-- One authoritative evaluation of a person program against the exact governing program curriculum
-- at a point in time, including overall unique-credit progress and aggregate requirement
-- satisfaction.
CREATE TABLE academics.person_program_progress_evaluation (
    tenant_identifier                                UUID NOT NULL,
    person_program_progress_evaluation_identifier    TEXT NOT NULL,
    person_program_identifier                        TEXT NOT NULL,
    program_curriculum_identifier                    TEXT NOT NULL,
    evaluation_date_time                             TIMESTAMP WITH TIME ZONE NOT NULL,
    total_credits_required                           NUMERIC,
    total_credits_applied                            NUMERIC,
    requirements_satisfied_indicator                 BOOLEAN NOT NULL DEFAULT FALSE,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_program_progress_evaluation PRIMARY KEY (tenant_identifier, person_program_progress_evaluation_identifier)
);
COMMENT ON TABLE academics.person_program_progress_evaluation IS 'One authoritative evaluation of a person program against the exact governing program curriculum at a point in time, including overall unique-credit progress and aggregate requirement satisfaction.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.person_program_progress_evaluation_identifier IS 'Unique identifier for one authoritative evaluation of a person program against a governing curriculum.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.person_program_identifier IS 'Person-program relationship whose progress is evaluated.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.program_curriculum_identifier IS 'Exact program curriculum whose requirements were used for this evaluation.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.evaluation_date_time IS 'Date and time at which the authoritative program-progress result was evaluated.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.total_credits_required IS 'Overall number of unique academic credits required under this evaluation when the curriculum is credit-based.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.total_credits_applied IS 'Overall number of unique academic credits recognized by this evaluation as counting toward the curriculum total.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.requirements_satisfied_indicator IS 'Indicates whether all requirements represented by this authoritative program-progress evaluation are satisfied.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.source_system_identifier IS 'Unique identifier for the source system that supplied the authoritative evaluation.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.source_system_key_value IS 'Unique identifier of this evaluation in the source system.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.created_date IS 'Date and time the canonical row was created.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.updated_date IS 'Date and time the canonical row was updated.';
COMMENT ON COLUMN academics.person_program_progress_evaluation.deleted_date IS 'Date and time the canonical row was logically deleted.';

-- PersonProgramRequirementEvaluation
-- The authoritative evaluated result for one program requirement within a person program progress
-- evaluation.
CREATE TABLE academics.person_program_requirement_evaluation (
    tenant_identifier                                UUID NOT NULL,
