    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_program_requirement_evaluation PRIMARY KEY (tenant_identifier, person_program_requirement_evaluation_identifier)
);
COMMENT ON TABLE academics.person_program_requirement_evaluation IS 'The authoritative evaluated result for one program requirement within a person program progress evaluation.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.person_program_requirement_evaluation_identifier IS 'Unique identifier for one evaluated program requirement within an authoritative program-progress evaluation.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.person_program_progress_evaluation_identifier IS 'Authoritative program-progress evaluation containing this requirement result.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.program_requirement_identifier IS 'Program requirement whose satisfaction was evaluated.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.requirement_satisfaction_status_identifier IS 'Governed evaluated satisfaction state of the program requirement.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.credits_satisfied IS 'Credits recognized as satisfying this requirement when the requirement evaluation expresses a credit quantity.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.courses_satisfied IS 'Number of courses recognized as satisfying this requirement when the requirement evaluation expresses a course count.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.exception_applied_indicator IS 'Indicates that an approved learner-specific exception altered the ordinary interpretation or satisfaction of this requirement.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.evaluation_note IS 'Optional human-readable explanation of the evaluated requirement result.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.source_system_identifier IS 'Unique identifier for the source system that supplied the requirement evaluation.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.source_system_key_value IS 'Unique identifier of this requirement evaluation in the source system.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.created_date IS 'Date and time the canonical row was created.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.updated_date IS 'Date and time the canonical row was updated.';
COMMENT ON COLUMN academics.person_program_requirement_evaluation.deleted_date IS 'Date and time the canonical row was logically deleted.';

-- PersonProgramRequirementEvidence
-- One item of evidence recognized by an authoritative requirement evaluation as contributing to
-- the evaluated result; credit-bearing evidence references LearnerAcademicCredit so provenance
-- remains traceable.
CREATE TABLE academics.person_program_requirement_evidence (
    tenant_identifier                                UUID NOT NULL,
    person_program_requirement_evidence_identifier   TEXT NOT NULL,
    person_program_requirement_evaluation_identifier TEXT NOT NULL,
    evidence_type_identifier                         TEXT NOT NULL,
    learner_academic_credit_identifier               TEXT,
    credits_counted                                  NUMERIC,
    evidence_description                             TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_program_requirement_evidence PRIMARY KEY (tenant_identifier, person_program_requirement_evidence_identifier)
);
COMMENT ON TABLE academics.person_program_requirement_evidence IS 'One item of evidence recognized by an authoritative requirement evaluation as contributing to the evaluated result; credit-bearing evidence references LearnerAcademicCredit so provenance remains traceable.';
COMMENT ON COLUMN academics.person_program_requirement_evidence.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.person_program_requirement_evidence.person_program_requirement_evidence_identifier IS 'Unique identifier for one item of evidence recognized as contributing to an evaluated program requirement.';
COMMENT ON COLUMN academics.person_program_requirement_evidence.person_program_requirement_evaluation_identifier IS 'Requirement evaluation to which this evidence contributed.';
COMMENT ON COLUMN academics.person_program_requirement_evidence.evidence_type_identifier IS 'Governed broad classification of the evidence recognized by the requirement evaluation.';
COMMENT ON COLUMN academics.person_program_requirement_evidence.learner_academic_credit_identifier IS 'Recognized learner academic credit used as evidence when the requirement is satisfied wholly or partly by credit-bearing academic work.';
COMMENT ON COLUMN academics.person_program_requirement_evidence.credits_counted IS 'Amount of the referenced learner academic credit counted toward this requirement when explicitly reported by the authoritative evaluation.';
COMMENT ON COLUMN academics.person_program_requirement_evidence.evidence_description IS 'Optional authoritative description of non-credit evidence or other evidence context not represented by LearnerAcademicCredit.';
COMMENT ON COLUMN academics.person_program_requirement_evidence.source_system_identifier IS 'Unique identifier for the source system that supplied the requirement-evidence result.';
