-- ProgramRequirement
-- An identifiable academic obligation belonging to a program curriculum. Requirements may be
-- hierarchical and may state broad credit/course expectations without encoding a universal
-- degree-audit rules language.
CREATE TABLE academics.program_requirement (
    tenant_identifier                                UUID NOT NULL,
    program_requirement_identifier                   TEXT NOT NULL,
    program_curriculum_identifier                    TEXT NOT NULL,
    parent_program_requirement_identifier            TEXT,
    requirement_type_identifier                      TEXT NOT NULL,
    code                                             TEXT,
    name                                             TEXT NOT NULL,
    description                                      TEXT,
    minimum_credits                                  NUMERIC,
    maximum_credits                                  NUMERIC,
    minimum_courses                                  INTEGER,
    sequence_number                                  INTEGER,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       TIMESTAMP WITH TIME ZONE,
    source_system_updated_date                       TIMESTAMP WITH TIME ZONE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_program_requirement PRIMARY KEY (tenant_identifier, program_requirement_identifier)
);
COMMENT ON TABLE academics.program_requirement IS 'An identifiable academic obligation belonging to a program curriculum. Requirements may be hierarchical and may state broad credit/course expectations without encoding a universal degree-audit rules language.';
COMMENT ON COLUMN academics.program_requirement.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.program_requirement.program_requirement_identifier IS 'Unique tenant-scoped identifier for a program requirement.';
COMMENT ON COLUMN academics.program_requirement.program_curriculum_identifier IS 'Curriculum to which this academic requirement belongs.';
COMMENT ON COLUMN academics.program_requirement.parent_program_requirement_identifier IS 'Optional parent requirement used to organize requirement groups or hierarchies.';
COMMENT ON COLUMN academics.program_requirement.requirement_type_identifier IS 'Governed broad classification of the academic obligation.';
COMMENT ON COLUMN academics.program_requirement.code IS 'Institutionally governed code for the requirement when one exists.';
COMMENT ON COLUMN academics.program_requirement.name IS 'Name of the academic requirement.';
COMMENT ON COLUMN academics.program_requirement.description IS 'Narrative description of the academic obligation.';
COMMENT ON COLUMN academics.program_requirement.minimum_credits IS 'Minimum credits required for this requirement when credit-based.';
COMMENT ON COLUMN academics.program_requirement.maximum_credits IS 'Maximum credits that may be applied to this requirement when applicable.';
COMMENT ON COLUMN academics.program_requirement.minimum_courses IS 'Minimum number of courses required when course-count based.';
COMMENT ON COLUMN academics.program_requirement.sequence_number IS 'Optional display or logical ordering within the curriculum or parent requirement.';
COMMENT ON COLUMN academics.program_requirement.source_system_identifier IS 'Identifier of the source system that supplied the record.';
COMMENT ON COLUMN academics.program_requirement.source_system_key_value IS 'Source-system identifier for the requirement.';
COMMENT ON COLUMN academics.program_requirement.source_system_created_date IS 'Date and time the source record was created.';
COMMENT ON COLUMN academics.program_requirement.source_system_updated_date IS 'Date and time the source record was last modified.';
COMMENT ON COLUMN academics.program_requirement.created_by IS 'Person identifier that created the record.';
COMMENT ON COLUMN academics.program_requirement.created_date IS 'Date record was created.';
COMMENT ON COLUMN academics.program_requirement.updated_by IS 'Person identifier that updated the record.';
COMMENT ON COLUMN academics.program_requirement.updated_date IS 'Date and time record was updated.';
COMMENT ON COLUMN academics.program_requirement.deleted_by IS 'Person identifier that deleted the record.';
COMMENT ON COLUMN academics.program_requirement.deleted_date IS 'Date and time record was deleted.';

-- ProgramRequirementCourse
-- An explicit descriptive association between a program requirement and a course that may be used
-- by institutional curriculum or degree-audit processes; the association does not itself determine
-- learner-specific satisfaction.
CREATE TABLE academics.program_requirement_course (
    tenant_identifier                                UUID NOT NULL,
    program_requirement_course_identifier            TEXT NOT NULL,
    program_requirement_identifier                   TEXT NOT NULL,
    course_identifier                                TEXT NOT NULL,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_program_requirement_course PRIMARY KEY (tenant_identifier, program_requirement_course_identifier)
);
COMMENT ON TABLE academics.program_requirement_course IS 'An explicit descriptive association between a program requirement and a course that may be used by institutional curriculum or degree-audit processes; the association does not itself determine learner-specific satisfaction.';
COMMENT ON COLUMN academics.program_requirement_course.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.program_requirement_course.program_requirement_course_identifier IS 'Unique tenant-scoped identifier for an explicit course-to-requirement association.';
COMMENT ON COLUMN academics.program_requirement_course.program_requirement_identifier IS 'Program requirement with which the course is explicitly associated.';
COMMENT ON COLUMN academics.program_requirement_course.course_identifier IS 'Course explicitly associated with the program requirement.';
COMMENT ON COLUMN academics.program_requirement_course.source_system_identifier IS 'Identifier of the source system that supplied the record.';
COMMENT ON COLUMN academics.program_requirement_course.source_system_key_value IS 'Source-system identifier for the association.';
COMMENT ON COLUMN academics.program_requirement_course.created_by IS 'Person identifier that created the record.';
COMMENT ON COLUMN academics.program_requirement_course.created_date IS 'Date record was created.';
COMMENT ON COLUMN academics.program_requirement_course.updated_by IS 'Person identifier that updated the record.';
COMMENT ON COLUMN academics.program_requirement_course.updated_date IS 'Date and time record was updated.';
COMMENT ON COLUMN academics.program_requirement_course.deleted_by IS 'Person identifier that deleted the record.';
COMMENT ON COLUMN academics.program_requirement_course.deleted_date IS 'Date and time record was deleted.';

-- ResultCategory
-- A category given to a grouping of results or grade items (e.g. "Homework", "Exams").
CREATE TABLE academics.result_category (
    tenant_identifier                                UUID NOT NULL,
    result_category_identifier                       TEXT NOT NULL,
    course_identifier                                TEXT,
    class_identifier                                 TEXT,
    source_system_identifier                         TEXT,
    name                                             TEXT NOT NULL,
    weight                                           NUMERIC,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_result_category PRIMARY KEY (tenant_identifier, result_category_identifier)
);
COMMENT ON TABLE academics.result_category IS 'A category given to a grouping of results or grade items (e.g. "Homework", "Exams").';
COMMENT ON COLUMN academics.result_category.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.result_category.result_category_identifier IS 'Unique identifier for the result category';
COMMENT ON COLUMN academics.result_category.course_identifier IS 'The actual code that identifies the organization of subject matter and related learning experiences provided for the instruction of students';
COMMENT ON COLUMN academics.result_category.class_identifier IS 'Unique identifier for the class';
COMMENT ON COLUMN academics.result_category.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN academics.result_category.name IS 'A name for the record';
COMMENT ON COLUMN academics.result_category.weight IS 'Total weight of this grading category in calculation of the course final score';
COMMENT ON COLUMN academics.result_category.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN academics.result_category.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN academics.result_category.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN academics.result_category.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN academics.result_category.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.result_category.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.result_category.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.result_category.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.result_category.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.result_category.deleted_date IS 'Date and time record was deleted';

-- Rubric
-- A table to describe a grouping of criterion for guiding the evaluation of an assessment or
-- assignment.
CREATE TABLE academics.rubric (
    tenant_identifier                                UUID NOT NULL,
    rubric_identifier                                TEXT NOT NULL,
    information_source_organization_identifier       TEXT,
    source_system_identifier                         TEXT,
    name                                             TEXT NOT NULL,
    description                                      TEXT,
    url                                              TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    status                                           TEXT NOT NULL,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_rubric PRIMARY KEY (tenant_identifier, rubric_identifier)
);
COMMENT ON TABLE academics.rubric IS 'A table to describe a grouping of criterion for guiding the evaluation of an assessment or assignment.';
COMMENT ON COLUMN academics.rubric.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.rubric.rubric_identifier IS 'Unique identifier for the rubric';
COMMENT ON COLUMN academics.rubric.information_source_organization_identifier IS 'Organization identifier for the source of the information provided';
COMMENT ON COLUMN academics.rubric.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN academics.rubric.name IS 'A name for the record';
COMMENT ON COLUMN academics.rubric.description IS 'A description for the record';
COMMENT ON COLUMN academics.rubric.url IS 'The URL location where the rubric may be found';
COMMENT ON COLUMN academics.rubric.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN academics.rubric.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN academics.rubric.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN academics.rubric.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN academics.rubric.status IS 'Status of the rubric (unspecified, active, deleted, archived, draft)';
COMMENT ON COLUMN academics.rubric.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.rubric.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.rubric.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.rubric.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.rubric.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.rubric.deleted_date IS 'Date and time record was deleted';

-- RubricCriterion
-- A table containing a specific evaluation component within a rubric.
CREATE TABLE academics.rubric_criterion (
    tenant_identifier                                UUID NOT NULL,
    rubric_criterion_identifier                      TEXT NOT NULL,
    rubric_identifier                                TEXT NOT NULL,
    name                                             TEXT NOT NULL,
    description                                      TEXT,
    category                                         TEXT,
    sequence_number                                  INTEGER,
    weight                                           NUMERIC,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_rubric_criterion PRIMARY KEY (tenant_identifier, rubric_criterion_identifier)
);
COMMENT ON TABLE academics.rubric_criterion IS 'A table containing a specific evaluation component within a rubric.';
COMMENT ON COLUMN academics.rubric_criterion.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.rubric_criterion.rubric_criterion_identifier IS 'Unique identifier for the rubric criterion';
COMMENT ON COLUMN academics.rubric_criterion.rubric_identifier IS 'Unique identifier for the rubric';
COMMENT ON COLUMN academics.rubric_criterion.name IS 'A name for the record';
COMMENT ON COLUMN academics.rubric_criterion.description IS 'A description for the record';
COMMENT ON COLUMN academics.rubric_criterion.category IS 'A textual label for category by which the rubric criterion may be grouped';
COMMENT ON COLUMN academics.rubric_criterion.sequence_number IS 'A numeric value representing this criterion''s position in the criteria list for this rubric';
COMMENT ON COLUMN academics.rubric_criterion.weight IS 'A numeric weight assigned to this rubric criterion, used for scored rubrics';
COMMENT ON COLUMN academics.rubric_criterion.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.rubric_criterion.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.rubric_criterion.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.rubric_criterion.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.rubric_criterion.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.rubric_criterion.deleted_date IS 'Date and time record was deleted';

-- RubricCriterionLevel
-- A table containing predefined performance levels representing a specific degree of achievement
-- of the rubric criterion.
CREATE TABLE academics.rubric_criterion_level (
    tenant_identifier                                UUID NOT NULL,
    rubric_criterion_level_identifier                TEXT NOT NULL,
    rubric_criterion_identifier                      TEXT NOT NULL,
    name                                             TEXT NOT NULL,
    description                                      TEXT,
    feedback                                         TEXT,
    sequence_number                                  INTEGER,
    quality_label                                    TEXT NOT NULL,
    score                                            NUMERIC NOT NULL,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_rubric_criterion_level PRIMARY KEY (tenant_identifier, rubric_criterion_level_identifier)
);
COMMENT ON TABLE academics.rubric_criterion_level IS 'A table containing predefined performance levels representing a specific degree of achievement of the rubric criterion.';
COMMENT ON COLUMN academics.rubric_criterion_level.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.rubric_criterion_level.rubric_criterion_level_identifier IS 'Unique identifier for the rubric criterion level';
COMMENT ON COLUMN academics.rubric_criterion_level.rubric_criterion_identifier IS 'Unique identifier for the rubric criterion';
COMMENT ON COLUMN academics.rubric_criterion_level.name IS 'A name for the record';
COMMENT ON COLUMN academics.rubric_criterion_level.description IS 'A description for the record';
COMMENT ON COLUMN academics.rubric_criterion_level.feedback IS 'Pre-defined feedback text to be relayed to the person or organization being evaluated This may include guidance and suggestions for improvement or development';
COMMENT ON COLUMN academics.rubric_criterion_level.sequence_number IS 'A numeric value representing the level''s position in the list of levels defined for the Rubric Criterion';
COMMENT ON COLUMN academics.rubric_criterion_level.quality_label IS 'A qualitative description of this degree of achievement used for column headers or row labels in tabular rubrics';
COMMENT ON COLUMN academics.rubric_criterion_level.score IS 'The points awarded for achieving this level';
COMMENT ON COLUMN academics.rubric_criterion_level.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.rubric_criterion_level.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.rubric_criterion_level.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.rubric_criterion_level.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.rubric_criterion_level.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.rubric_criterion_level.deleted_date IS 'Date and time record was deleted';

-- ScoreScale
-- A score scale or quality points scale available to be used with scored tests, assessments, and
-- assignments (e.g. letter grades to percentage).
CREATE TABLE academics.score_scale (
    tenant_identifier                                UUID NOT NULL,
    score_scale_identifier                           TEXT NOT NULL,
    source_system_identifier                         TEXT,
    name                                             TEXT NOT NULL,
    type                                             TEXT,
    status                                           TEXT NOT NULL,
    source_system_key_value                          TEXT,
    source_system_created_by                         TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_score_scale PRIMARY KEY (tenant_identifier, score_scale_identifier)
);
COMMENT ON TABLE academics.score_scale IS 'A score scale or quality points scale available to be used with scored tests, assessments, and assignments (e.g. letter grades to percentage).';
COMMENT ON COLUMN academics.score_scale.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.score_scale.score_scale_identifier IS 'Unique identifier for the score scale';
COMMENT ON COLUMN academics.score_scale.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN academics.score_scale.name IS 'A name for the record';
COMMENT ON COLUMN academics.score_scale.type IS 'The type of score scale mapping. At present there is no predefined vocabulary. This should be used by an organization to differentiate between the score scales that it produces.';
COMMENT ON COLUMN academics.score_scale.status IS 'Status of the score scale (active, inactive)';
COMMENT ON COLUMN academics.score_scale.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN academics.score_scale.source_system_created_by IS 'Person identifier that created the record in the source system';
COMMENT ON COLUMN academics.score_scale.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN academics.score_scale.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN academics.score_scale.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN academics.score_scale.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.score_scale.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.score_scale.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.score_scale.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.score_scale.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.score_scale.deleted_date IS 'Date and time record was deleted';

-- ScoreScaleValue
-- The mapping between two score scales or quality points (e.g. from "A" to "90-100").
CREATE TABLE academics.score_scale_value (
    tenant_identifier                                UUID NOT NULL,
    score_scale_value_identifier                     TEXT NOT NULL,
    object_value_lhs                                 TEXT NOT NULL,
    object_value_rhs                                 TEXT NOT NULL,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_score_scale_value PRIMARY KEY (tenant_identifier, score_scale_value_identifier)
);
COMMENT ON TABLE academics.score_scale_value IS 'The mapping between two score scales or quality points (e.g. from "A" to "90-100").';
COMMENT ON COLUMN academics.score_scale_value.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.score_scale_value.score_scale_value_identifier IS 'Unique identifier for the score scale value';
COMMENT ON COLUMN academics.score_scale_value.object_value_lhs IS 'The left hand side value of the mapping relationship. The format is either a single value (''x'') or a range (''x'' - ''y''). In the case of a single value this is considered to be the inclusive lower value for the implied range. When a range is specified (lower-to-upper) the values are inclusive.';
COMMENT ON COLUMN academics.score_scale_value.object_value_rhs IS 'The right hand side value of the mapping relationship. The format is either a single value (''x'') or a range (''x'' - ''y''). In the case of a single value this is considered to be the inclusive lower value for the implied range. When a range is specified (lower-to-upper) the values are inclusive.';
COMMENT ON COLUMN academics.score_scale_value.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.score_scale_value.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.score_scale_value.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.score_scale_value.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.score_scale_value.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.score_scale_value.deleted_date IS 'Date and time record was deleted';

