COMMENT ON COLUMN academics.section_registration_status_lookup.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.section_registration_status_lookup.section_registration_status_identifier IS 'GUIDE-owned tenant-scoped identifier for the status.';
COMMENT ON COLUMN academics.section_registration_status_lookup.code IS 'Institutionally governed registration-status code.';
COMMENT ON COLUMN academics.section_registration_status_lookup.title IS 'Display title of the registration status.';
COMMENT ON COLUMN academics.section_registration_status_lookup.description IS 'Description of the registration status.';
COMMENT ON COLUMN academics.section_registration_status_lookup.headcount_status_indicator IS 'Indicates whether registrations with this status count toward section headcount.';
COMMENT ON COLUMN academics.section_registration_status_lookup.active_indicator IS 'Indicates whether the status definition is available for current use.';
COMMENT ON COLUMN academics.section_registration_status_lookup.source_system_identifier IS 'Source system supplying the definition.';
COMMENT ON COLUMN academics.section_registration_status_lookup.source_system_key_value IS 'Source-system identifier for the status definition.';
COMMENT ON COLUMN academics.section_registration_status_lookup.created_date IS 'Date and time the canonical row was created.';
COMMENT ON COLUMN academics.section_registration_status_lookup.updated_date IS 'Date and time the canonical row was updated.';

-- SectionStatusLookup
