-- SyllabusScheduleItem
-- A table indicating an individual item that is outlined in the syllabus schedule. It may refer to
-- weekly schedule items, course modules, textbook chapters/sections, or any other division of
-- coursework outlined by the instructor over time.
CREATE TABLE academics.syllabus_schedule_item (
    tenant_identifier                                UUID NOT NULL,
    syllabus_schedule_item_identifier                TEXT NOT NULL,
    revision_identifier                              TEXT NOT NULL,
    syllabus_identifier                              TEXT NOT NULL,
    name                                             TEXT NOT NULL,
    description                                      TEXT,
    syllabus_schedule_item_revision_status           TEXT,
    sequence_number                                  INTEGER,
    date                                             DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    syllabus_revision_identifier                     TEXT NOT NULL,
    CONSTRAINT pk_syllabus_schedule_item PRIMARY KEY (tenant_identifier, syllabus_schedule_item_identifier, revision_identifier)
);
COMMENT ON TABLE academics.syllabus_schedule_item IS 'A table indicating an individual item that is outlined in the syllabus schedule. It may refer to weekly schedule items, course modules, textbook chapters/sections, or any other division of coursework outlined by the instructor over time.';
COMMENT ON COLUMN academics.syllabus_schedule_item.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.syllabus_schedule_item.syllabus_schedule_item_identifier IS 'Unique identifier for the syllabus schedule item';
COMMENT ON COLUMN academics.syllabus_schedule_item.revision_identifier IS 'Unique identifier for the revision to the syllabus schedule item';
COMMENT ON COLUMN academics.syllabus_schedule_item.syllabus_identifier IS 'Unique identifier for the syllabus';
COMMENT ON COLUMN academics.syllabus_schedule_item.name IS 'A name for the record';
COMMENT ON COLUMN academics.syllabus_schedule_item.description IS 'A description for the record';
COMMENT ON COLUMN academics.syllabus_schedule_item.syllabus_schedule_item_revision_status IS 'The status of the revision (e.g. draft, under review, accepted, rejected, published, closed)';
COMMENT ON COLUMN academics.syllabus_schedule_item.sequence_number IS 'Number indicating when, within the collection of scheduled items associated with this syllabus, this one should be completed';
COMMENT ON COLUMN academics.syllabus_schedule_item.date IS 'The date on which the scheduled item takes place according to the syllabus';
COMMENT ON COLUMN academics.syllabus_schedule_item.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.syllabus_schedule_item.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.syllabus_schedule_item.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.syllabus_schedule_item.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.syllabus_schedule_item.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.syllabus_schedule_item.deleted_date IS 'Date and time record was deleted';
COMMENT ON COLUMN academics.syllabus_schedule_item.syllabus_revision_identifier IS 'Revision of the Syllabus referenced by this record.';

