-- TermLookup
-- A lookup table that describes the academic terms offered by an organization.
CREATE TABLE academics.term_lookup (
    tenant_identifier                                UUID NOT NULL,
    term_identifier                                  TEXT NOT NULL,
    source_system_identifier                         TEXT,
    code                                             TEXT NOT NULL,
    code_name                                        TEXT NOT NULL,
    begin_date                                       DATE,
    end_date                                         DATE,
    type                                             TEXT,
    code_description                                 TEXT,
    registration_start_date                          DATE,
    registration_end_date                            DATE,
    withdrawal_deadline_date                         DATE,
    late_withdrawal_date                             DATE,
    school_financial_aid_application_due_date        DATE,
    weighted_gpa_scale                               NUMERIC,
    status                                           TEXT NOT NULL,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    academic_period_category                         TEXT,
    registration_status_identifier                   TEXT,
    CONSTRAINT pk_term_lookup PRIMARY KEY (tenant_identifier, term_identifier)
);
COMMENT ON TABLE academics.term_lookup IS 'A lookup table that describes the academic terms offered by an organization.';
COMMENT ON COLUMN academics.term_lookup.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN academics.term_lookup.term_identifier IS 'Unique identifier for a term';
COMMENT ON COLUMN academics.term_lookup.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN academics.term_lookup.code IS 'Code identifying the academic year and term';
COMMENT ON COLUMN academics.term_lookup.code_name IS 'Name of the academic term designator';
COMMENT ON COLUMN academics.term_lookup.begin_date IS 'Begin date for an academic term';
COMMENT ON COLUMN academics.term_lookup.end_date IS 'End date for an academic term';
COMMENT ON COLUMN academics.term_lookup.type IS 'Type of the academic term (quarter, semester, trimester, other)';
COMMENT ON COLUMN academics.term_lookup.code_description IS 'Description of the academic term designator';
COMMENT ON COLUMN academics.term_lookup.registration_start_date IS 'First date registration is open';
COMMENT ON COLUMN academics.term_lookup.registration_end_date IS 'Last date registration is open';
COMMENT ON COLUMN academics.term_lookup.withdrawal_deadline_date IS 'Normal withdrawal deadline date';
COMMENT ON COLUMN academics.term_lookup.late_withdrawal_date IS 'Late withdrawal deadline date';
COMMENT ON COLUMN academics.term_lookup.school_financial_aid_application_due_date IS 'Due date for financial aid application submission';
COMMENT ON COLUMN academics.term_lookup.weighted_gpa_scale IS 'Indicates the weighted GPA scale used during this term, such as 4.0, 5.0, 100, Other, School doesn''t calculate';
COMMENT ON COLUMN academics.term_lookup.status IS 'Status of the lookup item (active, inactive)';
COMMENT ON COLUMN academics.term_lookup.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN academics.term_lookup.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN academics.term_lookup.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN academics.term_lookup.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN academics.term_lookup.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN academics.term_lookup.created_date IS 'Date and time record was created';
COMMENT ON COLUMN academics.term_lookup.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN academics.term_lookup.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN academics.term_lookup.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN academics.term_lookup.deleted_date IS 'Date and time record was deleted';
COMMENT ON COLUMN academics.term_lookup.academic_period_category IS 'Category of the academic period in the source hierarchy.';
COMMENT ON COLUMN academics.term_lookup.registration_status_identifier IS 'Governed registration status for the academic period.';
